import{_ as r,o,c as n,a5 as a}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"870-根据excel指定列搜索图片并在指定列添加图片","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["EXCEL批处理"],"标签":["Excel图片嵌入","Python自动化","办公软件","图片搜索匹配","批量处理","效率工具","数据关联"]},"headers":[],"relativePath":"md/EXCEL批处理/870-根据excel指定列搜索图片并在指定列添加图片.md","filePath":"md/EXCEL批处理/870-根据excel指定列搜索图片并在指定列添加图片.md"}'),s={name:"md/EXCEL批处理/870-根据excel指定列搜索图片并在指定列添加图片.md"};function e(p,t,l,g,i,c){return o(),n("div",null,[...t[0]||(t[0]=[a('<p>用于将图片批量插入到Excel指定列的单元格中，支持宽度自适应、行高自动调整、图片居中/顶部/底部对齐等多种实用功能。</p><p>该工具能够根据Excel指定列中的文件名，自动搜索对应图片文件并将其以浮动方式嵌入到目标单元格中，大幅提升办公效率。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260116184828176856050880718.png" alt=""></p><h3 id="功能亮点" tabindex="-1">功能亮点 <a class="header-anchor" href="#功能亮点" aria-label="Permalink to &quot;功能亮点&quot;">​</a></h3><ul><li>支持批量处理：从Excel指定列读取图片文件名，自动在目标列插入对应图片，<strong>图片浮动于单元格上方</strong></li><li>图片宽度严格适配单元格宽度</li><li>行高自动根据图片高度自适应（无固定高度上限）</li><li>支持图片位置选择：顶部 / 居中（默认） / 底部</li><li>支持设置左右边距（默认5像素）</li><li>不区分图片文件大小写后缀（.jpg/.JPG/.png/.PNG 等均可）</li><li>支持递归查找图片（图片文件夹及其子文件夹均可）</li></ul><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多图片文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有图片文件。</p><p>【操作方法】：选择需要处理的excel文件，格式为xlsx，选择图片所在文件夹路径A，其他使用默认方式即可，运行程序开始处理</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260116185832176856111240021.png" alt=""></p><p><strong>程序会在原文件同目录生成新文件：原文件名_带图片.xlsx</strong></p><p>处理完成后如下图所示，原excel文档会保留，生成一个新的excel，可以避免因操作错误或其他情况导致原文档丢失。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260116185512176856091248717.png" alt=""></p><p>【1】、支持的文件格式：不区分扩展名大小写</p><p>&#39;.jpg&#39;, &#39;.jpeg&#39;, &#39;.png&#39;, &#39;.webp&#39;</p><p>【2】、是否支持子文件夹穿透：图片文件夹支持</p><h3 id="图片文件结构树示意" tabindex="-1">图片文件结构树示意 <a class="header-anchor" href="#图片文件结构树示意" aria-label="Permalink to &quot;图片文件结构树示意&quot;">​</a></h3><p><strong>文件夹A/ (主文件夹)</strong><br> ├── 文件1<br> ├── 文件2<br> ├── <strong>B/ (子文件夹)</strong><br> │   ├── 文件3<br> │   ├── <strong>子文件夹B1/</strong><br> │   │   ├── 文件4<br> │   │   └── <strong>子文件夹B1a/</strong><br> │   │       └── 文件5<br> │   └── <strong>子文件夹B2/</strong><br> │       └── 文件6<br> │       ... (B文件夹下可能还有更多子文件夹和文件)<br> ├── <strong>C/ (子文件夹)</strong><br> │   ├── 文件7<br> │   └── <strong>子文件夹C1/</strong><br> │       ├── 文件8<br> │       └── <strong>子文件夹C1a/</strong><br> │           └── 文件9<br> │           ... (C1a文件夹下可能还有更多嵌套)<br> └── <strong>D/ (子文件夹)</strong><br>     ├── 文件10<br>     └── <strong>子文件夹D1/</strong><br>         └── 文件11<br>         ... (D1文件夹下可能还有更多文件)<br><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p>注意：先测试备份原文件再批量使用</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q: 为什么有些图片没有成功嵌入？</strong></p><p>A: 可能原因包括：</p><ul><li>图片文件名与Excel单元格内容不匹配</li><li>图片文件损坏或格式不支持</li></ul><p><strong>Q: 如何处理文件名包含空格的情况？</strong></p><p>A: 工具支持包含空格的文件名，确保Excel中的文件名与图片文件名完全一致即可。</p><p><strong>Q: 能否处理多个Excel文件？</strong></p><p>A: 当前版本支持单个Excel文件处理，如需批量处理多个文件，建议分别处理或联系定制开发。</p><p><strong>Q: 图片嵌入后如何调整大小？</strong></p><p>A: 可以通过调整&quot;单元格宽度&quot;参数来控制图片显示尺寸，或使用Excel自带的图片调整功能。</p><p><strong>Q: 处理过程中出现错误怎么办？</strong></p><p>A: 查看日志窗口的错误信息，常见问题包括文件权限不足、路径错误、内存不足等。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>如下图所示：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260116233352176857763223878.png" alt=""></p><p><strong>双击快捷方式使用即可，快捷方式可以放到任意地方，文件夹名不能修该，文件夹内文件不能删除。</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2389.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2389.html</a></p>',41)])])}const _=r(s,[["render",e]]);export{h as __pageData,_ as default};
